/**
 * Bindings the api worker receives as `env` — one entry per binding in
 * wrangler.jsonc (hand-written rather than generated by `wrangler types`, so
 * the shape is reviewed with the config that declares it).
 */

export interface ApiBindings {
  /** "local" | "preview" | "prod" — from `vars` in wrangler.jsonc. */
  ENVIRONMENT: string;
  /** Postgres via Hyperdrive; locally the docker compose database. */
  HYPERDRIVE: Hyperdrive;
  /** Query-result cache, shared with pipeline (purge) and dashboard (purge). */
  CACHE: KVNamespace;
  /** Producer side of `proofql-ingest`; workers/pipeline consumes. */
  INGEST_QUEUE: Queue;
  /**
   * Workers AI for query embeddings. Bound in preview/prod only — there is
   * no local simulator — so code must treat it as optional.
   */
  AI?: Ai;
}

/** Hono generic: bindings on `c.env`. */
export type AppEnv = { Bindings: ApiBindings };
